const helpers = this.helpers;

// V4.3.7 - instrumentacao de latencia.
// Mede somente tempos; nao altera a logica do atendimento.
const workflowStartedAtMs = Date.now();
const timingMs = {};

function timingStart() {
  return Date.now();
}

function timingStop(label, startedAt) {
  const elapsed = Math.max(Date.now() - Number(startedAt || Date.now()), 0);
  timingMs[label] = Number(timingMs[label] || 0) + elapsed;
  return elapsed;
}

function timingSnapshot(extra = {}) {
  return {
    ...timingMs,
    ...extra,
    total_so_far: Math.max(Date.now() - workflowStartedAtMs, 0),
  };
}

const update = $json.body || $json;
const params = $json.params || {};
const query = $json.query || {};
const message = update.message || update.edited_message || update.channel_post || {};
const chat = message.chat || {};
const from = message.from || {};
const chatId = chat.id;

// Tempo aproximado entre o Telegram receber a mensagem e este Code node iniciar.
// A data do Telegram tem precisão de segundos.
const telegramReceivedAtMs = Number(message.date || 0) * 1000;
if (telegramReceivedAtMs > 0) {
  timingMs.telegram_to_code_start = Math.max(
    workflowStartedAtMs - telegramReceivedAtMs,
    0
  );
}

// rawText = texto de trabalho usado internamente pela IA.
// displayMessageText = texto que será salvo/exibido na conversa.
let rawText = String(message.text || message.caption || '').trim();
let originalTextOrCaption = rawText; // Alterado para let para permitir o agrupamento
let displayMessageText = originalTextOrCaption;
const tenantSlug = String(query.tenant_slug || query.tenant || params.tenant_slug || params.tenantSlug || $env.DEFAULT_TENANT_SLUG || 'jiw')
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9_-]/g, '');
const firstName = from.first_name || chat.first_name || 'tudo bem';
let normalized = rawText.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

function env(name, fallback = '') {
  let envValue = '';
  let varsValue = '';
  try {
    envValue = $env[name] || '';
  } catch (error) {}
  try {
    varsValue = $vars?.[name] || '';
  } catch (error) {}
  return envValue || varsValue || fallback;
}

function hasAny(words) {
  return words.some((word) => normalized.includes(word));
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function setCurrentText(value) {
  rawText = String(value || '').trim();
  normalized = rawText
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function isLikelyFragmentForDebounce(value = rawText) {
  const text = normalizeText(value);
  if (!text) return true;
  const compact = text.replace(/[^a-z0-9\s?!.]/g, ' ').replace(/\s+/g, ' ').trim();
  const words = compact.split(' ').filter(Boolean);
  const pureOpenings = ['oi', 'oie', 'oiii', 'ola', 'opa', 'bom dia', 'boa tarde', 'boa noite', 'coe', 'co?', 'salve', 'fala tu', 'e ai', 'e a?', 'teste'];
  if (pureOpenings.includes(compact)) return true;
  if (words.length <= 2 && !/[?!.]$/.test(compact)) return true;
  const danglingStarts = ['quero', 'queria', 'gostaria', 'preciso', 'sobre', 'algum', 'alguma', 'minha primeira vez', 'primeira vez', 'nao sei', 'n?o sei'];
  return danglingStarts.some((item) => compact === normalizeText(item) || compact.startsWith(normalizeText(item) + ' '));
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function settingsFor(context = {}) {
  return context.settings?.settings || {};
}

function tenantTimeZone(context = {}) {
  const settings = settingsFor(context);

  return String(
    context.settings?.timezone
    || settings.timezone
    || 'America/Sao_Paulo'
  ).trim() || 'America/Sao_Paulo';
}

function buildDateContext(context = {}) {
  const timeZone = tenantTimeZone(context);
  const now = new Date();
  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);

  const dateFormatter = new Intl.DateTimeFormat('pt-BR', {
    timeZone,
    weekday: 'long',
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });

  const timeFormatter = new Intl.DateTimeFormat('pt-BR', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });

  return {
    timeZone,
    today: dateFormatter.format(now),
    tomorrow: dateFormatter.format(tomorrow),
    currentTime: timeFormatter.format(now),
    generatedAt: now.toISOString(),
  };
}

function activePromptFor(context = {}) {
  const settings = settingsFor(context);
  return settings.system_prompt || context.promptVersion?.prompt || settings.prompt || settings.ai_prompt || '';
}

function removeMidConversationGreeting(text, hasHistory) {
  if (!hasHistory) return String(text || '').trim();

  const original = String(text || '').trim();
  const cleaned = original
    .replace(
      /^(?:oi|olá|ola|oie|bom dia|boa tarde|boa noite)(?:\s*,?\s*(?:linda|querida|meu amor|amor|flor|meu chapa))?[!,.:;\s✨💖🌸☀️👙-]*/i,
      ''
    )
    .trim();

  return cleaned || original;
}

function detectActions(text) {
  const value = String(text || '');
  return {
    humanRequested: /\[HUMANO_SOLICITADO\]/i.test(value),
    complaint: /\[(?:AÇÃO|ACAO)\s*:\s*RECLAMACAO\]/i.test(value) || /\[RECLAMACAO\]/i.test(value),
    readyToSchedule: /\[(?:AÇÃO|ACAO)\s*:\s*PRONTO_PARA_AGENDAR\]/i.test(value) || /\[PRONTO_PARA_AGENDAR\]/i.test(value),
  };
}

function cleanReplyText(text) {
  return String(text || '')
    // Tags internas: nunca devem aparecer para o cliente
    .replace(/\[(?:AÇÃO|ACAO)\s*:\s*[^\]]+\]/gi, '')
    .replace(/\[HUMANO_SOLICITADO\]/gi, '')
    .replace(/\[PRONTO_PARA_AGENDAR\]/gi, '')
    .replace(/\[RECLAMACAO\]/gi, '')

    // Desescapa Markdown que alguns modelos devolvem como "\*\*" / "\-"
    .replace(/\\([*_`~>#\-\[\]()])/g, '$1')

    // Remove Markdown e mantém texto legível no Telegram sem parse_mode
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^\s*#{1,6}\s*/gm, '')
    .replace(/^\s*[-*]\s+/gm, '• ')

    // Limpeza de espaços
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}


function containsEmoji(value) {
  return /[\p{Extended_Pictographic}\u2600-\u27BF]/u.test(
    String(value || '')
  );
}

function stripEmojis(value) {
  return String(value || '')
    .replace(/[\p{Extended_Pictographic}\u2600-\u27BF]/gu, '')
    .replace(/[\uFE0E\uFE0F\u200D\u20E3]/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +([,.!?;:])/g, '$1')
    .trim();
}

function previousAssistantUsedEmoji(history = []) {
  for (let index = history.length - 1; index >= 0; index -= 1) {
    const item = history[index];

    if (item?.response_text) {
      return containsEmoji(item.response_text);
    }

    if (item?.direction === 'outbound' && item?.message_text) {
      return containsEmoji(item.message_text);
    }
  }

  return false;
}

function enforceEmojiPolicy(text, history = [], classification = {}) {
  let output = String(text || '');

  const sensitive =
    classification?.handoff === true
    || normalizeText(classification?.stage).includes('atendimento humano')
    || normalizeText(classification?.service).includes('reclamacao');

  if (sensitive) {
    return stripEmojis(output);
  }

  let seenEmoji = false;

  output = output.replace(
    /[\p{Extended_Pictographic}\u2600-\u27BF]/gu,
    (emoji) => {
      if (seenEmoji) return '';
      seenEmoji = true;
      return emoji;
    }
  );

  if (seenEmoji && previousAssistantUsedEmoji(history)) {
    output = stripEmojis(output);
  }

  return output
    .replace(/[\uFE0E\uFE0F\u200D\u20E3]/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +([,.!?;:])/g, '$1')
    .trim();
}

function isBotFrustrationText() {
  const value = normalizeText(rawText);
  return [
    'ia burra',
    'ia idiota',
    'bot burro',
    'bot idiota',
    'voce e burra',
    'voce e burro',
    'você é burra',
    'você é burro',
    'responde direito',
    'responda direito',
    'nao foi isso',
    'não foi isso',
    'voce nao entendeu',
    'você não entendeu',
    'que resposta ruim',
    'que resposta merda',
    'ta burra',
    'tá burra',
    'burra do caralho',
    'burro do caralho',
  ].some((term) => value.includes(normalizeText(term)));
}

function isRealServiceComplaintText() {
  const value = normalizeText(rawText);
  return [
    'reclamacao do atendimento',
    'reclamação do atendimento',
    'fui mal atendida',
    'fui mal atendido',
    'quero meu dinheiro de volta',
    'dinheiro de volta',
    'estorno',
    'reembolso',
    'procon',
    'ouvidoria',
    'procedimento deu errado',
    'resultado ficou ruim',
    'resultado horrivel',
    'resultado horrível',
    'me queimou',
    'queimadura',
    'me machucou',
    'machucou minha pele',
    'problema com o procedimento',
    'problema no atendimento',
  ].some((term) => value.includes(normalizeText(term)));
}
function audienceSignals() {
  const value = normalizeText(rawText);

  const selfMaleSignals = [
    'sou homem',
    'sou um homem',
    'sou masculino',
    'sou do sexo masculino',
    'quero fazer em mim',
    'quero fazer pra mim e sou homem',
    'quero fazer para mim e sou homem',
  ];

  const bookingForOtherFemaleSignals = [
    'minha esposa',
    'pra minha esposa',
    'para minha esposa',
    'minha namorada',
    'pra minha namorada',
    'para minha namorada',
    'minha amiga',
    'pra minha amiga',
    'para minha amiga',
    'minha filha',
    'pra minha filha',
    'para minha filha',
    'minha irmã',
    'minha irma',
    'pra minha irmã',
    'para minha irmã',
    'para outra pessoa',
