function formatCatalogPrice(item = {}) {
  if (item.price === null || item.price === undefined || item.price === '') {
    return 'preço sob consulta';
  }

  const numeric = Number(item.price);

  if (!Number.isFinite(numeric)) {
    return String(item.price);
  }

  return 'R$ ' + numeric.toFixed(2).replace('.', ',');
}

function validateFullCatalogRows(rows = []) {
  const validRows = Array.isArray(rows)
    ? rows.filter((item) => item && item.active !== false)
    : [];

  const invalidRows = validRows.filter((item) =>
    !String(item.name || '').trim()
  );

  return {
    valid: validRows.length > 0 && invalidRows.length === 0,
    count: validRows.length,
    reason: validRows.length === 0
      ? 'empty_catalog'
      : invalidRows.length
        ? 'invalid_catalog_rows'
        : '',
  };
}

function buildFullCatalogReplyFromRows(rows = []) {
  const activeRows = Array.isArray(rows)
    ? rows.filter((item) => item && item.active !== false)
    : [];

  if (!activeRows.length) return '';

  const grouped = new Map();
  const categories = [];

  for (const item of activeRows) {
    const category = String(item.category || 'Outros').trim() || 'Outros';

    if (!grouped.has(category)) {
      grouped.set(category, []);
      categories.push(category);
    }

    grouped.get(category).push(item);
  }

  const blocks = categories.map((category) => {
    const lines = (grouped.get(category) || []).map(
      (item) => `• ${item.name || 'Serviço'} — ${formatCatalogPrice(item)}`
    );

    return `${category}:\n${lines.join('\n')}`;
  });

  return `${divaCatalogIntro()}\n\n${blocks.join('\n\n')}`;
}


function catalogTokens(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .map((token) => token.trim())
    .filter((token) => token.length >= 3);
}

function levenshteinDistance(left = '', right = '') {
  const a = normalizeText(left);
  const b = normalizeText(right);

  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;

  const previous = Array.from(
    { length: b.length + 1 },
    (_, index) => index
  );

  for (let i = 1; i <= a.length; i += 1) {
    const current = [i];

    for (let j = 1; j <= b.length; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;

      current[j] = Math.min(
        current[j - 1] + 1,
        previous[j] + 1,
        previous[j - 1] + cost
      );
    }

    for (let j = 0; j < current.length; j += 1) {
      previous[j] = current[j];
    }
  }

  return previous[b.length];
}

function fuzzyTokenSimilarity(left = '', right = '') {
  const a = normalizeText(left);
  const b = normalizeText(right);

  if (!a || !b) return 0;
  if (a === b) return 1;

  if (a.includes(b) || b.includes(a)) {
    const shorter = Math.min(a.length, b.length);
    const longer = Math.max(a.length, b.length);
    return Math.max(0.84, shorter / Math.max(longer, 1));
  }

  const distance = levenshteinDistance(a, b);
  const maxLen = Math.max(a.length, b.length, 1);
  return Math.max(0, 1 - distance / maxLen);
}

function scoreCatalogItemForQuery(item = {}, query = '') {
  const queryNormalized = normalizeText(query);
  const name = normalizeText(item.name || '');
  const category = normalizeText(item.category || '');
  const description = normalizeText(item.description || '');
  const notes = normalizeText(item.notes || '');

  if (!queryNormalized || !name) return 0;

  let score = 0;

  if (queryNormalized.includes(name)) {
    score += 100;
  }

  if (name.includes(queryNormalized) && queryNormalized.length >= 4) {
    score += 80;
  }

  const queryTokens = catalogTokens(query);
  const nameTokens = catalogTokens(item.name || '');
  const categoryTokens = catalogTokens(item.category || '');

  let bestNameSimilarity = 0;

  for (const queryToken of queryTokens) {
    for (const nameToken of nameTokens) {
      bestNameSimilarity = Math.max(
        bestNameSimilarity,
        fuzzyTokenSimilarity(queryToken, nameToken)
      );
    }
  }

  // Erros comuns como:
  // conforti -> comfort
  // premiun -> premium
  // clasico -> clássico
  if (bestNameSimilarity >= 0.70) {
    score += bestNameSimilarity * 70;
  }

  for (const queryToken of queryTokens) {
    if (nameTokens.includes(queryToken)) score += 28;
    if (categoryTokens.includes(queryToken)) score += 10;

    if (
      description.includes(queryToken)
      || notes.includes(queryToken)
    ) {
      score += 4;
    }
  }

  return score;
}

function rankCatalogRowsLocally(rows = [], query = '', limit = 8) {
  const ranked = (Array.isArray(rows) ? rows : [])
    .filter((item) => item && item.active !== false)
    .map((item) => ({
      item,
      score: scoreCatalogItemForQuery(item, query),
    }))
    .filter((entry) => entry.score >= 38)
    .sort((left, right) => right.score - left.score)
    .slice(0, Math.max(1, limit));

  // Evita mandar vários serviços irrelevantes quando existe um match muito forte.
  if (ranked.length && ranked[0].score >= 70) {
    const topScore = ranked[0].score;
    return ranked
      .filter((entry) => entry.score >= Math.max(42, topScore - 22))
      .map((entry) => ({
        ...entry.item,
        _local_match_score: Number(entry.score.toFixed(2)),
      }));
  }

  return ranked.map((entry) => ({
    ...entry.item,
    _local_match_score: Number(entry.score.toFixed(2)),
  }));
}

function divaCatalogIntro() {
  const value = normalizeText(rawText);

  if (
    value.includes('miga')
    || value.includes('amiga')
    || value.includes('diva')
    || value.includes('gata')
  ) {
    return 'Miga, claro! Separei tudo bonitinho para você — olha só os serviços e valores:';
  }

  return 'Aí sim! Separei tudo bonitinho para você — olha só os nossos serviços e valores:';
}

function catalogRowsToContext(rows = []) {
  return rows.map((item, index) => {
    const price =
      item.price === null || item.price === undefined
        ? 'preco sob consulta'
        : 'R$ ' + Number(item.price).toFixed(2).replace('.', ',');

    const unit = item.billing_unit
      ? ' Unidade: ' + item.billing_unit + '.'
      : '';

    const notes = item.notes
      ? ' Observacoes: ' + item.notes + '.'
      : '';

    const fuzzyScore = Number.isFinite(Number(item._local_match_score))
      ? ` Match fuzzy interno: ${Number(item._local_match_score).toFixed(2)}.`
      : '';

    return `${index + 1}. ${item.name || 'Item'} (${item.category || 'geral'}): ${item.description || 'sem descricao'}. Valor: ${price}.${unit}${notes}${fuzzyScore}`;
  }).join('\n');
}

async function loadCatalogContext(context = {}) {
  // O catálogo é a fonte de verdade comercial. Ativo por padrão.
  const enabled =
    String(env('TENANT_CATALOG_ENABLED', 'true')).toLowerCase() === 'true';

  if (!enabled || !rawText) {
    return {
      matches: [],
      context: '',
      mode: enabled ? 'empty_message' : 'disabled',
      isComplete: false,
    };
  }

  const fullCatalog = wantsFullCatalogRequest();

  try {
    if (fullCatalog) {
      const tenantId = context?.tenant?.id;

      if (!tenantId) {
        throw new Error('tenant_id ausente para carregar catalogo completo');
      }

      // Pedido de "todos": busca todos os itens ativos do tenant.
      const path =
        '/rest/v1/tenant_service_catalog'
        + '?select=external_id,category,name,description,price,billing_unit,estimated_hours,notes,active'
        + '&tenant_id=eq.' + encodeFilter(tenantId)
        + '&active=eq.true'
        + '&order=category.asc,name.asc'
        + '&limit=100';

      const result = await supabaseGet(path);
      const rows = Array.isArray(result) ? result : [];

      const validation = validateFullCatalogRows(rows);

      return {
        matches: rows,
        context: catalogRowsToContext(rows),
        mode: validation.valid ? 'full_db' : 'full_db_invalid',
        isComplete: validation.valid,
        validation,
      };
    }

    // Dúvida específica:
    // 1) tenta a RPC existente;
    // 2) busca todos os itens ativos do tenant;
    // 3) aplica fuzzy local para tolerar erros como "conforti", "premiun", "clasico".
    let rpcRows = [];

    try {
      const matches = await supabasePost(
        '/rest/v1/rpc/search_tenant_service_catalog',
        {
          p_tenant_slug: tenantSlug,
          p_query: rawText,
          p_limit: 8,
        }
      );

      rpcRows = Array.isArray(matches) ? matches : [];
    } catch (rpcError) {
      rpcRows = [];
    }

    const tenantId = context?.tenant?.id;

    let allRows = [];

    if (tenantId) {
      const allPath =
        '/rest/v1/tenant_service_catalog'
        + '?select=external_id,category,name,description,price,billing_unit,estimated_hours,notes,active'
        + '&tenant_id=eq.' + encodeFilter(tenantId)
        + '&active=eq.true'
        + '&order=category.asc,name.asc'
        + '&limit=100';

      allRows = await supabaseGet(allPath).catch(() => []);
    }

    const localRows = rankCatalogRowsLocally(
      Array.isArray(allRows) ? allRows : [],
      rawText,
      8
    );

    const deduped = [];
    const seen = new Set();

    for (const item of [...localRows, ...rpcRows]) {
      const key = String(
        item?.external_id
        || item?.id
        || item?.name
        || ''
      ).trim().toLowerCase();

      if (!key || seen.has(key)) continue;

      seen.add(key);
      deduped.push(item);

      if (deduped.length >= 8) break;
    }

    return {
      matches: deduped,
      context: catalogRowsToContext(deduped),
      mode: localRows.length
        ? 'search_fuzzy_db'
        : rpcRows.length
          ? 'search_rpc'
          : 'search_no_match',
      isComplete: false,
      fuzzy: {
        local_matches: localRows.length,
        rpc_matches: rpcRows.length,
        top_local_score: localRows[0]?._local_match_score ?? null,
      },
    };
  } catch (error) {
    return {
      matches: [],
      context: '',
      mode: fullCatalog ? 'full_error' : 'search_error',
      isComplete: false,
      error: error.message || String(error),
    };
