  timingStop('tenant_context', tenantContextStartedAt);

  const requestDateContext = buildDateContext(context);
  const contactName = [from.first_name, from.last_name].filter(Boolean).join(' ') || chat.title || 'Contato Telegram';
  const externalConversationId = String(chatId);
  const externalMessageId = message.message_id ? String(message.message_id) : `${chatId}:${Date.now()}`;

  // Telegram pode reenviar update em algumas situações. Não responda duas vezes ao mesmo message_id.
  const dedupStartedAt = timingStart();
  const isDuplicateMessage = message.message_id
    ? await alreadyProcessedExternalMessage(externalMessageId)
    : false;
  timingStop('dedup_lookup', dedupStartedAt);

  if (isDuplicateMessage) {
    return {
      json: {
        ok: true,
        skipped: true,
        reason: 'duplicate_telegram_message',
        chat_id: chatId,
        skip_response: true,
        telegram_response: {
          method: 'noop',
          chat_id: chatId,
          text: '',
        },
      },
    };
  }

  // --- INÍCIO: SISTEMA DE DEBOUNCE E AGRUPAMENTO DE MENSAGENS (5 SEGUNDOS) ---
  const configuredDebounceWindow = Number(settingsFor(context).debounce_window_ms || env('TELEGRAM_DEBOUNCE_WINDOW_MS', 8000));
  const configuredFragmentDebounceWindow = Number(settingsFor(context).fragment_debounce_window_ms || env('TELEGRAM_FRAGMENT_DEBOUNCE_WINDOW_MS', 15000));
  const baseDebounceWindowMs = Number.isFinite(configuredDebounceWindow)
    ? Math.max(3000, Math.min(configuredDebounceWindow, 12000))
    : 8000;
  const fragmentDebounceWindowMs = Number.isFinite(configuredFragmentDebounceWindow)
    ? Math.max(baseDebounceWindowMs, Math.min(configuredFragmentDebounceWindow, 20000))
    : 15000;
  const debounceWindowMs = isLikelyFragmentForDebounce(rawText)
    ? fragmentDebounceWindowMs
    : baseDebounceWindowMs;
  const bufferEvent = {
    tenant_slug: tenantSlug,
    channel_type: 'telegram',
    external_conversation_id: externalConversationId,
    external_message_id: externalMessageId,
    direction: 'inbound',
    sender_type: 'contact',
    contact_name: contactName,
    contact_handle: from.username || '',
    message_text: rawText,
    service: 'geral',
    stage: 'Buffering',
    handoff: false,
    response_text: null,
    ai_provider: 'buffer',
    ai_model: null,
    ai_error: '',
    ai_usage: {},
    raw_payload: {
      telegram_update: update,
      telegram_message: message,
      has_media: Boolean(detectTelegramMedia(message)),
      debounce_window_ms: debounceWindowMs,
      base_debounce_window_ms: baseDebounceWindowMs,
      fragment_debounce_window_ms: fragmentDebounceWindowMs,
      likely_fragment_for_debounce: isLikelyFragmentForDebounce(rawText),
      debounce_key: `${tenantSlug}:telegram:${externalConversationId}`
    },
  };

  const savedBuffer = await saveEvent(bufferEvent);

  // Mantém uma janela de 5 segundos para receber mensagens repartidas.
  // O último processamento da janela junta todos os textos antes de chamar o Gemini.
  await new Promise(resolve => setTimeout(resolve, debounceWindowMs));

  // Busca eventos que estão em Buffering nesta conversa
  const bufferPath = `/rest/v1/channel_events?select=id,message_text,external_message_id,created_at,raw_payload&tenant_slug=eq.${encodeFilter(tenantSlug)}&channel_type=eq.telegram&external_conversation_id=eq.${encodeFilter(externalConversationId)}&stage=eq.Buffering&order=created_at.asc,id.asc&limit=20`;
  const bufferRows = await supabaseGet(bufferPath).catch(() => []);

  if (Array.isArray(bufferRows) && bufferRows.length > 0) {
    let latestEvent = bufferRows[bufferRows.length - 1];

    if (latestEvent.id !== savedBuffer.id) {
      return {
        json: {
          ok: true,
          skipped: true,
          reason: 'agrupado_com_mensagem_recente',
          chat_id: chatId,
          skip_response: true,
          telegram_response: { method: 'noop', chat_id: chatId, text: '' },
        },
      };
    }

    // Janela de silencio real: se a ultima mensagem ainda e recente, aguarda o restante
    // e consulta novamente antes de responder. Isso reduz respostas multiplas em mensagens fragmentadas.
    const latestCreatedAtMs = Date.parse(latestEvent.created_at || '');
    const latestAgeMs = Number.isFinite(latestCreatedAtMs)
      ? Date.now() - latestCreatedAtMs
      : debounceWindowMs;
    const remainingQuietMs = debounceWindowMs - latestAgeMs;

    if (remainingQuietMs > 250) {
      await new Promise(resolve => setTimeout(resolve, Math.min(remainingQuietMs + 250, debounceWindowMs)));
      const refreshedRows = await supabaseGet(bufferPath).catch(() => []);
      if (Array.isArray(refreshedRows) && refreshedRows.length > 0) {
        const refreshedLatestEvent = refreshedRows[refreshedRows.length - 1];
        if (refreshedLatestEvent.id !== savedBuffer.id) {
          return {
            json: {
              ok: true,
              skipped: true,
              reason: 'agrupado_com_mensagem_recente_apos_janela_silencio',
              chat_id: chatId,
              skip_response: true,
              telegram_response: { method: 'noop', chat_id: chatId, text: '' },
            },
          };
        }
        bufferRows.splice(0, bufferRows.length, ...refreshedRows);
        latestEvent = refreshedLatestEvent;
      }
    }

    const combinedText = bufferRows
      .map((r) => String(r.message_text || '').trim())
      .filter(Boolean)
      .join('\n\n');

    if (combinedText) {
      setCurrentText(combinedText);
      displayMessageText = combinedText;
      originalTextOrCaption = combinedText;
    }

    // Adoção de Mídia: se a mensagem atual não tem mídia, mas uma agrupada anterior tinha, herde a mídia!
    const currentMedia = detectTelegramMedia(message);
    if (!currentMedia) {
      const mediaRows = bufferRows.filter(r => r.raw_payload && r.raw_payload.has_media);
      if (mediaRows.length > 0) {
        const adoptedMessage = mediaRows[mediaRows.length - 1].raw_payload.telegram_message;
        if (adoptedMessage.photo) message.photo = adoptedMessage.photo;
        if (adoptedMessage.voice) message.voice = adoptedMessage.voice;
        if (adoptedMessage.audio) message.audio = adoptedMessage.audio;
        if (adoptedMessage.document) message.document = adoptedMessage.document;
        if (adoptedMessage.video) message.video = adoptedMessage.video;
        if (adoptedMessage.sticker) message.sticker = adoptedMessage.sticker;
        if (adoptedMessage.video_note) message.video_note = adoptedMessage.video_note;
      }
    }

    // Remove todos os eventos temporários do banco para manter o histórico limpo
    const idsToDelete = bufferRows.map((r) => r.id);
    if (idsToDelete.length > 0) {
      await httpJson(
        'DELETE',
        supabaseUrl(`/rest/v1/channel_events?id=in.(${idsToDelete.join(',')})`),
        supabaseHeaders()
      ).catch(() => {});
    }
  }
  // --- FIM: SISTEMA DE DEBOUNCE E AGRUPAMENTO ---

  const historyStartedAt = timingStart();
  const controlHistory = await loadRecentHistory();
  timingStop('history_load', historyStartedAt);

  // Controle de handoff/encerramento olha uma janela grande.
  // O Gemini recebe apenas os 12 eventos mais recentes após a última fronteira.
  const history = historyAfterControlBoundary(controlHistory)
    .filter((event) => normalizeText(event.ai_provider) !== 'buffer')
    .slice(-6);

  // Reset explícito da memória desta conversa.
  if (normalized === '/reset' || normalized === 'reset') {
    const resetText = 'Conversa reiniciada ✨ Pode mandar sua próxima mensagem que começamos do zero.';

    const resetEvent = {
      tenant_slug: tenantSlug,
      channel_type: 'telegram',
      external_conversation_id: externalConversationId,
      external_message_id: externalMessageId,
      direction: 'inbound',
      sender_type: 'contact',
      contact_name: contactName,
      contact_handle: from.username || '',
      message_text: rawText,
      service: 'geral',
      stage: 'Reset',
      handoff: false,
      response_text: resetText,
      ai_provider: 'conversation_reset',
      ai_model: null,
      ai_error: '',
      ai_usage: {},
      raw_payload: {
        telegram_update: update,
        reset: true,
        ai_diagnostics: {
          timing_ms: timingSnapshot(),
        },
      },
    };

    await saveEvent(resetEvent);

    return {
      json: {
        ok: true,
        ...resetEvent,
        chat_id: chatId,
        telegram_response: {
          method: 'sendMessage',
          chat_id: chatId,
          text: resetText,
          disable_web_page_preview: true,
        },
      },
    };
  }

  const media = detectTelegramMedia(message);
  const mediaAiEnabled = String(settingsFor(context).media_ai_enabled || env('MEDIA_AI_ENABLED', 'false')).toLowerCase() === 'true';
  if (media && !mediaAiEnabled) {
    media.supported = false;
    media.unsupportedReason = 'media_ai_disabled';
  }

  if (media) {
    if (originalTextOrCaption) {
      // Se a pessoa enviou legenda, o painel mostra a própria legenda.
      displayMessageText = originalTextOrCaption;
    } else if (media.category === 'audio') {
      displayMessageText = '[Áudio recebido]';
    } else if (media.category === 'image' && media.kind === 'sticker') {
      displayMessageText = '[Figurinha recebida]';
    } else if (media.category === 'image') {
      displayMessageText = '[Imagem recebida]';
    } else if (media.category === 'video') {
      displayMessageText = '[Vídeo recebido]';
    } else {
      displayMessageText = '[Arquivo recebido]';
    }
  }

  let mediaProcessing = {
    present: Boolean(media),
    kind: media?.kind || '',
    category: media?.category || '',
    supported: media?.supported ?? false,
    mime_type: media?.mimeType || '',
    file_size_reported: Number(media?.fileSize || 0),
    downloaded_bytes: 0,
    duration_seconds: Number(media?.duration || 0),
    width: Number(media?.width || 0),
    height: Number(media?.height || 0),
    extracted_text: '',
    model: '',
    finish_reason: '',
    error: '',
    error_code: '',
    usage: {},
  };

  let forcedMediaResponse = '';

  if (media) {
    if (!media.supported) {
      mediaProcessing.error_code =
        media.unsupportedReason
        || 'media_type_not_supported';

      mediaProcessing.error =
        'Tipo de midia ainda nao habilitado nesta versao';

      if (!rawText) {
        forcedMediaResponse = mediaFallbackText(
          media,
          mediaProcessing.error_code
        );

        setCurrentText(
          media.category === 'video'
            ? '[Vídeo recebido]'
            : media.kind === 'sticker'
              ? '[Figurinha recebida]'
              : '[Arquivo recebido]'
        );
      }
    } else {
      try {
        const mediaAnalysisStartedAt = timingStart();
        const analyzed = await analyzeTelegramMedia(
          context,
          media
        );
        timingStop('media_analysis', mediaAnalysisStartedAt);

        mediaProcessing = {
          ...mediaProcessing,
          supported: true,
          mime_type: analyzed.mimeType,
          downloaded_bytes: analyzed.bytes,
          extracted_text: analyzed.text,
          model: analyzed.model,
          finish_reason: analyzed.finishReason,
          usage: analyzed.usage || {},
        };

        if (media.category === 'audio') {
          setCurrentText(
            originalTextOrCaption
              ? `${originalTextOrCaption}\n\nTranscrição do áudio:\n${analyzed.text}`
              : analyzed.text
          );
        } else if (media.category === 'image') {
          setCurrentText(
            originalTextOrCaption
              ? `${originalTextOrCaption}\n\nConteúdo observado na imagem:\n${analyzed.text}`
              : `A pessoa enviou uma imagem.\n\nConteúdo observado:\n${analyzed.text}`
          );
        }
      } catch (error) {
        // Se houve excecao durante a analise, ainda registramos o tempo gasto.
        if (!Object.prototype.hasOwnProperty.call(timingMs, 'media_analysis')) {
          timingMs.media_analysis = 0;
        }

        mediaProcessing.error =
          error.message || String(error);

        mediaProcessing.error_code =
          error.code || 'media_processing_error';

        // Se há uma legenda, ainda conseguimos responder ao texto.
        // Só forçamos fallback de mídia quando não há texto algum.
        if (!rawText) {
          forcedMediaResponse = mediaFallbackText(
            media,
            mediaProcessing.error_code
          );

          setCurrentText(
            media.category === 'audio'
              ? '[Áudio recebido, mas não foi possível transcrever]'
              : '[Imagem recebida, mas não foi possível analisar]'
          );
        }
      }
    }
  }

  const classification = classify(context);

  const appointmentsStartedAt = timingStart();
  const appointmentResult = await loadAppointments(context.tenant.id);
  timingStop('appointments_load', appointmentsStartedAt);

  const appointments = appointmentState(appointmentResult.rows);
  const control = conversationControl(controlHistory);

  if (control.lockedByHuman) {
    const lockedEvent = {
      tenant_slug: tenantSlug,
      channel_type: 'telegram',
      external_conversation_id: externalConversationId,
      external_message_id: externalMessageId,
      direction: 'inbound',
      sender_type: 'contact',
      contact_name: contactName,
      contact_handle: from.username || '',
      message_text: rawText,
      service: 'atendimento_humano',
      stage: 'Atendimento humano',

      // IMPORTANTE:
      // isto significa "mensagem recebida enquanto havia lock",
      // não um NOVO pedido de handoff.
      handoff: false,

      response_text: null,
      ai_provider: 'human_lock',
      ai_model: null,
      ai_error: '',
      ai_usage: {},
      raw_payload: {
        telegram_update: update,
        human_lock_source: control.lockSource,
        human_lock_event: control.lockEvent ? {
          created_at: control.lockEvent.created_at || null,
          sender_type: control.lockEvent.sender_type || null,
          sent_by_user: control.lockEvent.sent_by_user || null,
          ai_provider: control.lockEvent.ai_provider || null,
          stage: control.lockEvent.stage || null,
          handoff: Boolean(control.lockEvent.handoff),
        } : null,
        active_history_count: control.activeHistory.length,
        ai_diagnostics: {
          timing_ms: timingSnapshot({
            history_events_loaded: Array.isArray(controlHistory) ? controlHistory.length : 0,
          }),
        },
        appointment_state: {
          has_confirmed: appointments.hasConfirmed,
          has_passed: appointments.hasPassed,
        },
      },
    };
    await saveEvent(lockedEvent);
    return {
      json: {
        ok: true,
        ...lockedEvent,
        chat_id: chatId,
        skip_response: true,
        human_lock: true,
        telegram_response: {
          method: 'noop',
          chat_id: chatId,
          text: '',
        },
      },
    };
  }

  const catalogStartedAt = timingStart();
  const catalog = await loadCatalogContext(context);
  timingStop('catalog_load', catalogStartedAt);

  const fallback = fallbackAnswer(context, classification, appointments);
  const gate = usageGate(context);

  const fullCatalogRequestedNow = wantsFullCatalogRequest();

  const directCatalogReply =
    fullCatalogRequestedNow
    && catalog?.isComplete
    && Array.isArray(catalog.matches)
    && catalog.matches.length > 0
      ? buildFullCatalogReplyFromRows(catalog.matches)
      : '';

  let responseText = directCatalogReply || forcedMediaResponse || fallback;

  let aiProvider = directCatalogReply
    ? 'catalog_db_direct'
    : forcedMediaResponse
      ? 'media_fallback'
      : 'fallback_rules';

  let aiModel = directCatalogReply
    ? null
    : env(
        'GEMINI_MODEL',
        'gemini-2.5-flash-lite'
      );

  let aiError = forcedMediaResponse
    ? mediaProcessing.error
    : '';

  let aiUsage = directCatalogReply
    ? {
        promptTokenCount: 0,
        thoughtsTokenCount: 0,
        candidatesTokenCount: 0,
        totalTokenCount: 0,
        catalog_db_items: Array.isArray(catalog.matches)
          ? catalog.matches.length
          : 0,
      }
    : {};

  let fallbackReason = directCatalogReply
    ? 'catalog_db_direct'
    : forcedMediaResponse
      ? (
        mediaProcessing.error_code
        || 'media_fallback'
      )
      : 'fallback_rules_default';

  if (directCatalogReply) {
    // Lista completa vem diretamente do tenant_service_catalog.
    // Não chama Gemini, não consome daily limit e não sofre truncamento da geração.
  } else if (forcedMediaResponse) {
    // Já existe uma resposta específica para a mídia.
  } else if (rawText && gate.allowed) {
    try {
      const geminiCallStartedAt = timingStart();
      const gemini = await callGemini(
        context,
        classification,
        fallback,
        history,
        catalog,
        appointments
      );
      timingStop('gemini_total', geminiCallStartedAt);

      responseText = gemini.text;
      aiProvider = 'gemini';
      aiModel = gemini.model;
      aiUsage = gemini.usage;
      fallbackReason = '';

      markUsage();
    } catch (error) {
      // Em caso de erro, mantém o fallback já preparado.
      // Não classificamos linguisticamente a mensagem no código.
      aiProvider = 'fallback_gemini_error';
      aiError = error.message || String(error);
      fallbackReason = 'gemini_request_error';
    }
  } else if (gate.forceMock) {
    aiProvider = 'mock_rules';
    fallbackReason = 'tenant_ai_mock_or_disabled';
  } else if (!gate.enabled) {
    aiProvider = 'fallback_gemini_disabled';
    fallbackReason = 'gemini_disabled_by_environment';
  } else if (!gate.hasKey) {
    aiProvider = 'fallback_no_gemini_key';
    fallbackReason = 'gemini_api_key_missing';
  } else if (
    gate.hasDailyLimit
    && gate.usedToday >= gate.dailyLimit
  ) {
    aiProvider = 'fallback_daily_limit';
    fallbackReason = 'internal_daily_limit_reached';
  }
  const actions = detectActions(responseText);
  const botFrustrationOnly = isBotFrustrationText() && !isRealServiceComplaintText();
  const complaintHandoff = actions.complaint && !botFrustrationOnly;
  const readyToSchedule = actions.readyToSchedule;

  let handoff = Boolean(
    classification.handoff
    || actions.humanRequested
    || complaintHandoff
    || readyToSchedule
  );

  // Xingamento/frustração com a resposta da IA não é reclamação formal da clínica.
  if (botFrustrationOnly && !actions.humanRequested && !isRealServiceComplaintText()) {
    handoff = false;
  }

  let visibleResponse = cleanReplyText(responseText);

  if (handoff) {
    const normalizedVisible = normalizeText(visibleResponse);
    const alreadyMentionsTeamForwarding = [
      'vou encaminhar',
      'vou passar para a equipe',
      'vou enviar para a equipe',
      'equipe confirmar',
      'equipe vai confirmar',
      'confirmar a disponibilidade',
      'finalizar o agendamento',
    ].some((term) => normalizedVisible.includes(normalizeText(term)));

    if (!alreadyMentionsTeamForwarding) {
      const teamNotice = readyToSchedule
        ? 'Vou encaminhar essas informações para a equipe confirmar a disponibilidade e finalizar o agendamento.'
        : 'Vou encaminhar isso para a equipe continuar com você.';

      visibleResponse = `${visibleResponse}\n\n${teamNotice}`.trim();
    }
  }

  const cleanResponse = enforceEmojiPolicy(
    removeMidConversationGreeting(
      cleanReplyText(visibleResponse),
      history.length > 0
    ),
    history,
    classification
  );

  const event = {
    tenant_slug: tenantSlug,
    channel_type: 'telegram',
    external_conversation_id: externalConversationId,
    external_message_id: externalMessageId,
    direction: 'inbound',
    sender_type: 'contact',
    contact_name: contactName,
    contact_handle: from.username || '',
    // O painel recebe somente o texto real/placeholder da mídia.
    // A descrição/transcrição interna fica em raw_payload.media_processing.
    message_text: displayMessageText || rawText,
    service: classification.service,
    stage: complaintHandoff
      ? 'Atendimento humano'
      : readyToSchedule
        ? 'Agendamento'
        : classification.stage,
    handoff,
    response_text: cleanResponse,
    ai_provider: aiProvider,
    ai_model: aiModel,
    ai_error: aiError,
    ai_usage: aiUsage,
    catalog_matches: catalog.matches || [],
    catalog_error: catalog.error || '',
    gemini_daily_limit: gate.dailyLimit,
    gemini_used_today_before_request: gate.usedToday,
    raw_payload: {
      telegram_update: update,

      // Separação intencional:
      // - display_message_text: pode aparecer no painel.
      // - processed_message_text: contexto interno usado pela IA.
      // - media_processing.extracted_text: descrição/transcrição multimodal.
      display_message_text: displayMessageText || rawText,
      original_text_or_caption: originalTextOrCaption,
      processed_message_text: rawText,
      media_processing: mediaProcessing,
      date_context: {
        timezone: requestDateContext.timeZone,
        today: requestDateContext.today,
        tomorrow: requestDateContext.tomorrow,
        current_time: requestDateContext.currentTime,
        generated_at: requestDateContext.generatedAt,
      },
      catalog_lookup: {
        mode: catalog.mode || null,
        is_complete: Boolean(catalog.isComplete),
        count: Array.isArray(catalog.matches) ? catalog.matches.length : 0,
        error: catalog.error || '',
      },
      ai_diagnostics: {
        provider: aiProvider,
        fallback_reason: fallbackReason,
        ai_error: aiError,
        gate: {
          enabled: gate.enabled,
          has_key: gate.hasKey,
          force_mock: gate.forceMock,
          allowed: gate.allowed,
          has_daily_limit: gate.hasDailyLimit,
          daily_limit: gate.dailyLimit,
          used_today_before_text_response: gate.usedToday,
          remaining_before_text_response: gate.hasDailyLimit
            ? Math.max(gate.dailyLimit - gate.usedToday, 0)
            : null,
        },
        usage: aiUsage,
        gemini_gate: {
          enabled: Boolean(gate.enabled),
          has_key: Boolean(gate.hasKey),
          force_mock: Boolean(gate.forceMock),
          allowed: Boolean(gate.allowed),
          daily_limit: Number(gate.dailyLimit || 0),
          used_today: Number(gate.usedToday || 0),
          remaining_today: gate.hasDailyLimit
            ? Math.max(
                Number(gate.dailyLimit || 0)
                - Number(gate.usedToday || 0),
                0
              )
            : null,
        },
        response_mode: directCatalogReply
          ? 'catalog_db_direct'
          : 'gemini_conversational',
        fast_path_enabled: false,
        catalog_db_direct: Boolean(directCatalogReply),
        catalog_db_items: directCatalogReply && Array.isArray(catalog.matches)
          ? catalog.matches.length
          : 0,
        timing_ms: timingSnapshot({
          history_events_loaded: Array.isArray(controlHistory) ? controlHistory.length : 0,
          history_events_sent_to_gemini: Array.isArray(history) ? history.length : 0,
          prompt_tokens: Number(aiUsage?.promptTokenCount || 0),
          thoughts_tokens: Number(aiUsage?.thoughtsTokenCount || 0),
          output_tokens: Number(aiUsage?.candidatesTokenCount || 0),
          gemini_http_ms: Number(aiUsage?.gemini_http_ms || 0),
          gemini_http_call_count: Number(aiUsage?.gemini_http_call_count || 0),
          base_prompt_chars: Number(aiUsage?.base_prompt_chars || 0),
          system_text_chars: Number(aiUsage?.system_text_chars || 0),
          gemini_contents_items: Number(aiUsage?.history_items_sent || 0),
        }),
      },
      appointment_state: {
        has_confirmed: appointments.hasConfirmed,
        has_passed: appointments.hasPassed,
        confirmed: appointments.futureConfirmed ? {
          id: appointments.futureConfirmed.id,
          title: appointments.futureConfirmed.title,
          starts_at: appointments.futureConfirmed.starts_at,
        } : null,
        passed: appointments.passed ? {
          id: appointments.passed.id,
          title: appointments.passed.title,
          starts_at: appointments.passed.starts_at,
        } : null,
      },
      appointment_lookup_error: appointmentResult.error || '',

      catalog_lookup: {
        requested_full_catalog: Boolean(fullCatalogRequestedNow),
        source: directCatalogReply
          ? 'tenant_service_catalog'
          : (catalog?.mode || 'none'),
        direct_db_response: Boolean(directCatalogReply),
        is_complete: Boolean(catalog?.isComplete),
        item_count: Array.isArray(catalog?.matches)
          ? catalog.matches.length
          : 0,
        validation: catalog?.validation || null,
        fuzzy: catalog?.fuzzy || null,
        error: catalog?.error || '',
      },

      internal_actions: {
        human_requested: actions.humanRequested,
        complaint: actions.complaint,
        complaint_handoff: complaintHandoff,
        ready_to_schedule: readyToSchedule,
        bot_frustration_only: botFrustrationOnly,
        audience: audienceSignals(),
        explicit_age: explicitAgeFromText(),
      },
    },
  };

  // Momento imediatamente anterior ao INSERT final.
  event.raw_payload.ai_diagnostics.timing_ms.total_before_save =
    Math.max(Date.now() - workflowStartedAtMs, 0);

  const eventSaveStartedAt = timingStart();
  await saveEvent(event);
  timingStop('event_save', eventSaveStartedAt);

  const runtimeTimingMs = timingSnapshot({
    total_after_save: Math.max(Date.now() - workflowStartedAtMs, 0),
  });

  return {
    json: {
      ok: true,
      ...event,
      runtime_timing_ms: runtimeTimingMs,
      chat_id: chatId,
      telegram_response: {
        method: 'sendMessage',
        chat_id: chatId,
        text: cleanResponse,
        disable_web_page_preview: true,
      },
    },
  };
} catch (error) {
  const errorMessage = error?.message || String(error);
  const messageText = 'Tive um problema para processar sua mensagem agora. Pode tentar novamente em alguns segundos?';

  // V4.4.4:
  // Registra falhas técnicas no channel_events para que apareçam no painel.
  // Erro técnico não ativa human-lock automaticamente.
  try {
    const errorContactName =
      [from.first_name, from.last_name].filter(Boolean).join(' ')
      || chat.title
      || 'Contato Telegram';

    const errorExternalConversationId = String(chatId);
    const errorExternalMessageId = message.message_id
      ? String(message.message_id)
      : `${chatId}:${Date.now()}`;

    const errorEvent = {
      tenant_slug: tenantSlug,
      channel_type: 'telegram',
      external_conversation_id: errorExternalConversationId,
      external_message_id: errorExternalMessageId,
      direction: 'inbound',
      sender_type: 'contact',
      contact_name: errorContactName,
      contact_handle: from.username || '',
      message_text: displayMessageText || rawText || '[Mensagem recebida]',
      service: 'system_error',
      stage: 'Erro de processamento',
      handoff: false,
      response_text: messageText,
      ai_provider: 'workflow_error',
      ai_model: null,
      ai_error: errorMessage,
      sent_by_user: false,
      raw_payload: {
        telegram_update: update,
        display_message_text: displayMessageText || rawText || '',
        original_text_or_caption: originalTextOrCaption || '',
        processed_message_text: rawText || '',
        workflow_error: {
          name: error?.name || 'Error',
          message: errorMessage,
          source: 'telegram_multitenant_code_node',
          version: '4.5.1',
        },
        ai_diagnostics: {
          provider: 'workflow_error',
          ai_error: errorMessage,
          fallback_reason: 'workflow_exception',
          timing_ms: timingSnapshot({
            failed: true,
            total_before_error_save: Math.max(
              Date.now() - workflowStartedAtMs,
              0
            ),
          }),
        },
      },
    };

    await saveEvent(errorEvent);
  } catch (saveError) {
    // Não mascara o erro original se o Supabase também estiver indisponível.
  }

  return {
    json: {
      ok: false,
      tenant_slug: tenantSlug,
      channel_type: 'telegram',
      chat_id: chatId,
      error: errorMessage,
      telegram_response: {
        method: 'sendMessage',
        chat_id: chatId,
        text: messageText,
        disable_web_page_preview: true,
      },
    },
  };
}
